/**
 * The entity page's reads, on `src/api/schema.d.ts` — generated by `make types`
 * from the real pydantic models and held to the tree by `make lint-generated`.
 *
 * Do NOT hand-declare these shapes. The card and its `Signal` are not restated
 * here: they belong to contract C8 and live in `types/brief.ts`, which is where
 * every other surface already imports them from.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

/**
 * One row of the connections list. Not a `GraphEdge`: it is read from ONE
 * name's point of view, so the other end arrives already named and `direction`
 * is resolved against the entity being viewed. `edge_id` comes from the server
 * and goes back verbatim -- assembled here it is backwards for every incoming
 * connection.
 */
export type Connection = Schemas['Connection']

/** `GET /entities/{id}/connections`. */
export type EntityConnections = Schemas['EntityConnections']

/** `GET /entities/{id}/sources`. Items are `Signal`, the same shape the card's
 *  recent articles use. */
export type EntitySources = Schemas['EntitySources']

/** `GET /entities/{id}/record` — admin only. Where a name came from. */
export type EntityRecord = Schemas['EntityRecord']
export type MergedName = Schemas['MergedName']
export type AliasOrigin = Schemas['AliasOrigin']

/** `GET /edges/{edge_id}/provenance` — the evidence behind one connection. */
export type EdgeProvenance = Schemas['EdgeProvenanceResponse']
